// HTML에서 뉴스 항목 추출 및 파싱을 한 번에 처리
const html = $json.data;
const results = [];

// 뉴스 항목을 찾는 정규식 패턴
const newsPattern = /<a class="lis"[^>]*href="[^"]*Homepage=([^"&]*)"[^>]*>([^<]*)<\/a>[\s\S]*?<td[^>]*align="center"[^>]*>([\d.]+)<\/td>/gi;

let match;
while ((match = newsPattern.exec(html)) !== null && results.length < 5) {
  const url = decodeURIComponent(match[1]);
  const fullText = match[2].trim();

  // 제목과 신문사 분리
  const parts = fullText.split('::');
  if (parts.length >= 2) {
    const title = parts[0].trim();
    const publisher = parts[1].trim();
    const date = match[3];

    results.push({
      title,
      publisher,
      url,
      date
    });
  }
}

return results.map(item => ({ json: item }));

// 기사 본문에서 텍스트 추출 및 요약 생성
const html = $json.data;
const newsData = $('process_each_news').item.json;

// HTML 태그 제거 및 본문 추출
function extractMainContent(html) {
  // 스크립트, 스타일, 광고 관련 태그 제거
  let cleaned = html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<\/?(?:nav|header|footer|aside|menu|advertisement)[^>]*>/gi, '');

  // HTML 태그 제거하고 텍스트만 추출
  cleaned = cleaned.replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/&[a-zA-Z0-9#]+;/g, ' ')
    .trim();

  // 본문으로 보이는 부분 추출 (긴 문단 우선)
  const sentences = cleaned.split(/[.!?]\s+/).filter(s => s.length > 20);
  return sentences.slice(0, 5).join('. ').substring(0, 500);
}

const mainContent = extractMainContent(html);

// 간단한 요약 생성 (첫 2-3 문장)
const summary = mainContent.split(/[.!?]\s+/)
  .filter(s => s.length > 10)
  .slice(0, 2)
  .join('. ')
  .substring(0, 100) + (mainContent.length > 100 ? '...' : '');

return [{
  json: {
    ...newsData,
    summary: summary || newsData.title.substring(0, 50) + '...'
  }
}];

// 디스코드 메시지 포맷팅
const articles = $json.articles;
const today = new Date().toLocaleDateString('ko-KR', { 
  year: 'numeric', 
  month: 'long', 
  day: 'numeric' 
});

let message = `🎨 **${today} 문화·예술 뉴스**\n오늘의 문화·예술 소식을 전해드립니다!\n\n`;

const emojis = ['1️⃣', '2️⃣', '3️⃣', '4️⃣', '5️⃣'];

articles.forEach((article, index) => {
  if (index < 5) {
    message += `**${emojis[index]} [${article.title}](${article.url})**\n`;
    message += `> ${article.summary}\n`;
    message += `📰 ${article.publisher} | 📅 ${article.date}\n\n`;
  }
});

return [{ json: { content: message } }];
